1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
6	  return Buffer.concat(chunks).toString("utf8");
7	};
8	
9	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
10	
11	const main = async (): Promise<void> => {
12	  const scenario = parseScenario(await readStdin());
13	  const result = runScenario(scenario);
14	  process.stdout.write(JSON.stringify(result));
15	};
16	
17	try {
18	  await main();
19	} catch (error) {
20	  // The MHPCO reports the objection itself, not the machinery behind it.
21	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
22	  process.exitCode = 1;
23	}
