1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  /** Zero-based index of the quote step that created the policy. */
21	  policy: number;
22	  incident: { cause: string; damages: Damage[] };
23	};
24	
25	export type Step = QuoteStep | ClaimStep;
26	
27	export type Customer = {
28	  yearsWithMHPCO: number;
29	};
30	
31	export type Scenario = {
32	  customer: Customer;
33	  steps: Step[];
34	};
35	
36	export type ScenarioResult = {
37	  results: unknown[];
38	};
39	
40	const PROCESSING_FEE = 5;
41	
42	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
43	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The item types the MHPCO will insure, and what each costs to cover. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** The MHPCO declines to quote for anything outside its price list. */
56	export class UninsurableItemError extends Error {
57	  constructor(type: string) {
58	    super(`The MHPCO does not insure items of type "${type}"`);
59	    this.name = "UninsurableItemError";
60	  }
61	}
62	
63	/**
64	 * Reads an item type out of one of the MHPCO's price lists. A type the list does not
65	 * name is a type the MHPCO does not insure, whichever list is being consulted.
66	 */
67	const requireInsurable =
68	  (priceList: Record<string, number>) =>
69	  (type: string): number => {
70	    const price = priceList[type];
71	    if (price === undefined) throw new UninsurableItemError(type);
72	    return price;
73	  };
74	
75	/** Premium for a single item of this type. */
76	const unitPremiumFor = requireInsurable(BASE_PREMIUMS);
77	
78	/** Component types that form discounted blocks. */
79	const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
80	const COMPONENT_BLOCK_SIZE = 3;
81	const COMPONENT_BLOCK_PREMIUM = 60;
82	
83	const formsComponentBlock = (type: string, count: number): boolean =>
84	  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
85	
86	/** How many items of each type the policy covers. */
87	const countByType = (items: Item[]): Map<string, number> =>
88	  items.reduce(
89	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
90	    new Map<string, number>(),
91	  );
92	
93	/** Alike components form a discounted block; everything else is priced per unit. */
94	const basePremiumForGroup = (type: string, count: number): number =>
95	  formsComponentBlock(type, count)
96	    ? COMPONENT_BLOCK_PREMIUM
97	    : count * unitPremiumFor(type);
98	
99	const policyBasePremium = (items: Item[]): number =>
100	  [...countByType(items)].reduce(
101	    (total, [type, count]) => total + basePremiumForGroup(type, count),
102	    0,
103	  );
104	
105	/** A modifier that applies to some subject, contributing a rate when it does. */
106	type ModifierRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
107	
108	/** Modifier rates stack additively — at both the item and the policy level. */
109	const sumApplicableRates = <Subject>(
110	  rules: ModifierRule<Subject>[],
111	  subject: Subject,
112	): number =>
113	  rules.reduce((total, rule) => (rule.applies(subject) ? total + rule.rate : total), 0);
114	
115	const CURSE_SURCHARGE_RATE = 0.5;
116	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
117	const HIGH_ENCHANTMENT_THRESHOLD = 5;
118	
119	/** Each risk an item can carry, and the surcharge rate it attracts. */
120	const ITEM_SURCHARGE_RULES: ModifierRule<Item>[] = [
121	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
122	  {
123	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
124	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
125	  },
126	];
127	
128	/** Item-level surcharge rates stack additively on one item. */
129	const surchargeRateFor = (item: Item): number =>
130	  sumApplicableRates(ITEM_SURCHARGE_RULES, item);
131	
132	/**
133	 * Item-level surcharges apply to the affected item's own base premium, not to
134	 * the policy total.
135	 */
136	const itemSurchargeTotal = (items: Item[]): number =>
137	  items.reduce(
138	    (total, item) => total + unitPremiumFor(item.type) * surchargeRateFor(item),
139	    0,
140	  );
141	
142	const LOYALTY_DISCOUNT_RATE = 0.2;
143	const LOYALTY_YEARS_THRESHOLD = 2;
144	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
145	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
146	
147	/** A quote in the context of the customer's history with the MHPCO. */
148	type Contract = {
149	  customer: Customer;
150	  /** How many contracts this customer already held when this quote was made. */
151	  precedingContracts: number;
152	};
153	
154	/** Each policy-level modifier, and the rate it contributes. Discounts are negative. */
155	const POLICY_MODIFIER_RULES: ModifierRule<Contract>[] = [
156	  {
157	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
158	    rate: -LOYALTY_DISCOUNT_RATE,
159	  },
160	  // Every quote insures its items for the first time, whatever the customer's history.
161	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
162	  {
163	    applies: ({ precedingContracts }) => precedingContracts > 0,
164	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
165	  },
166	];
167	
168	/**
169	 * Policy-level modifiers are percentages of the policy base premium and stack
170	 * additively, per the MHPCO's worked examples.
171	 */
172	const policyModifierRate = (contract: Contract): number =>
173	  sumApplicableRates(POLICY_MODIFIER_RULES, contract);
174	
175	/**
176	 * Every modifier is a percentage of a base premium, and they are summed as flat
177	 * amounts rather than compounded: item surcharges are percentages of the affected
178	 * item's own base premium, policy modifiers percentages of the policy base premium
179	 * (the sum of all item base premiums, before any surcharge).
180	 */
181	const quotePremium = (items: Item[], contract: Contract): number => {
182	  const policyBase = policyBasePremium(items);
183	  const policyModifiers = policyBase * policyModifierRate(contract);
184	  const total = policyBase + itemSurchargeTotal(items) + policyModifiers + PROCESSING_FEE;
185	  return roundUpToWholeG(total);
186	};
187	
188	/** What each item type contributes to a policy's insurance sum. */
189	const INSURED_VALUE_BY_TYPE: Record<string, number> = {
190	  sword: 1000,
191	  amulet: 600,
192	  staff: 800,
193	  potion: 400,
194	  rune: 250,
195	  moonstone: 250,
196	};
197	
198	const DEDUCTIBLE_PER_DAMAGE = 100;
199	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
200	
201	/** Payouts round down — in the MHPCO's favour. Float noise is discarded first. */
202	const roundDownToWholeG = (amount: number): number => Math.floor(Number(amount.toFixed(6)));
203	
204	/** A policy created by a quote step, tracked across the claims made against it. */
205	type Policy = {
206	  items: Item[];
207	  remainingCap: number;
208	};
209	
210	const insuredValueFor = requireInsurable(INSURED_VALUE_BY_TYPE);
211	
212	/**
213	 * The insurance sum is the plain sum of insured values — block discounts and premium
214	 * modifiers affect what the policy costs, never what it covers.
215	 */
216	const insuranceSum = (items: Item[]): number =>
217	  items.reduce((sum, item) => sum + insuredValueFor(item.type), 0);
218	
219	const openPolicy = (items: Item[]): Policy => ({
220	  items,
221	  remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
222	});
223	
224	/** The MHPCO pays only for what a policy actually covers. */
225	export class UncoveredDamageError extends Error {
226	  constructor(itemType: string) {
227	    super(`The policy does not cover an item of type "${itemType}"`);
228	    this.name = "UncoveredDamageError";
229	  }
230	}
231	
232	/** The MHPCO does not entertain damage reports for negative amounts. */
233	export class InvalidDamageAmountError extends Error {
234	  constructor(amount: number) {
235	    super(`A damage amount cannot be negative, but was ${amount}`);
236	    this.name = "InvalidDamageAmountError";
237	  }
238	}
239	
240	/** A damage the MHPCO is willing to look at, or no damage at all. */
241	const requireReportable = (damage: Damage): Damage => {
242	  if (damage.amount < 0) throw new InvalidDamageAmountError(damage.amount);
243	  return damage;
244	};
245	
246	/** A damage and the specific insured item it was matched against. */
247	type MatchedDamage = { damage: Damage; item: Item };
248	
249	/**
250	 * Pairs each reported damage with the insured item it refers to, rejecting anything
251	 * the MHPCO will not settle. Every damage consumes a distinct item, so a policy
252	 * covering one sword cannot absorb two sword damages.
253	 */
254	const matchDamagesToItems = (policy: Policy, damages: Damage[]): MatchedDamage[] => {
255	  const unclaimed = [...policy.items];
256	
257	  return damages.map((reported) => {
258	    const damage = requireReportable(reported);
259	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
260	    if (index === -1) throw new UncoveredDamageError(damage.itemType);
261	    return { damage, item: unclaimed.splice(index, 1)[0] };
262	  });
263	};
264	
265	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
266	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
267	const FULL_REIMBURSEMENT_RATE = 1;
268	
269	/**
270	 * How much of the damage the MHPCO reimburses, before the deductible. Claim clauses
271	 * do not stack the way premium modifiers do — the strongest applicable clause decides
272	 * the rate on its own.
273	 */
274	const reimbursementRateFor = (item: Item): number =>
275	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
276	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
277	    : FULL_REIMBURSEMENT_RATE;
278	
279	/** A deductible applies once per damaged item, and never turns a payout negative. */
280	const payoutForDamage = ({ damage, item }: MatchedDamage): number =>
281	  Math.max(0, damage.amount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE);
282	
283	/**
284	 * Settling a claim yields both the payout and the policy as it stands afterwards —
285	 * each claim eats into the cap available to the next one.
286	 */
287	const settleClaim = (
288	  policy: Policy,
289	  damages: Damage[],
290	): { settlement: { payout: number; remainingCap: number }; policy: Policy } => {
291	  const uncappedPayout = matchDamagesToItems(policy, damages).reduce(
292	    (total, matched) => total + payoutForDamage(matched),
293	    0,
294	  );
295	  const payout = roundDownToWholeG(Math.min(uncappedPayout, policy.remainingCap));
296	  const remainingCap = policy.remainingCap - payout;
297	  return { settlement: { payout, remainingCap }, policy: { ...policy, remainingCap } };
298	};
299	
300	/**
301	 * The policies a scenario has opened so far, keyed by the index of the quote step
302	 * that opened them — which is how claim steps refer back to them.
303	 */
304	type PolicyRegister = Map<number, Policy>;
305	
306	/** A quote opens a policy, priced against the contracts the customer already holds. */
307	const quoteStepResult = (
308	  step: QuoteStep,
309	  stepIndex: number,
310	  register: PolicyRegister,
311	  customer: Customer,
312	) => {
313	  const precedingContracts = register.size;
314	  register.set(stepIndex, openPolicy(step.items));
315	  return { premium: quotePremium(step.items, { customer, precedingContracts }) };
316	};
317	
318	/** A claim settles against its policy and leaves that policy with less cap. */
319	const claimStepResult = (step: ClaimStep, register: PolicyRegister) => {
320	  const { settlement, policy } = settleClaim(
321	    register.get(step.policy)!,
322	    step.incident.damages,
323	  );
324	  register.set(step.policy, policy);
325	  return settlement;
326	};
327	
328	export const runScenario = (scenario: Scenario): ScenarioResult => {
329	  const register: PolicyRegister = new Map();
330	
331	  const results = scenario.steps.map((step, index) =>
332	    step.op === "claim"
333	      ? claimStepResult(step, register)
334	      : quoteStepResult(step, index, register, scenario.customer),
335	  );
336	
337	  return { results };
338	};
